"""The narrow word alias binds the original pointer and preserves old fixtures."""
from dataclasses import asdict,replace
import hashlib

import pytest

from tools.kb.tests import test_injection_start_delay_chain as publication


def inputs():
    module=publication.stock_module()
    image=bytearray(0x9000)
    image[0x1000:0x1002]=bytes.fromhex('84ec')
    image[0x1004:0x1008]=bytes.fromhex('ffff128c')
    region=module.Region(key='word-alias-contract',rom='JK08A',source='probe.s',harness='probe.c',
        start=0x2000,end=0x2010,pools=((0x1000,8),),ram_literals=(0x1004,),cases=1,
        ram_word_literals=((0x1000,0xffff84ec,0x7f00,1),))
    return module,region,bytes(image)

def test_word_alias_changes_only_the_declared_pool_bytes_and_boundary():
    module,region,image=inputs()
    assert module.ram_word_aliases(region,image)==region.ram_word_literals
    expected=bytearray(image)
    expected[0x1000:0x1002]=bytes.fromhex('7f00')
    expected[0x1004:0x1008]=bytes.fromhex('0100128c')
    expected[0x2010:0x2014]=bytes.fromhex('000b0009')
    assert module.build_fixture(region,image)==expected
    assert module.build_fixture(region,image)[region.start:region.end]==image[region.start:region.end]

@pytest.mark.parametrize('kind',('list','shape','bool','odd','pool','original','positive-original','negative-alias',
    'signed-alias','extent','origin-end','alias-end','code','boundary','data','duplicate','origin-overlap',
    'alias-overlap','pool-overlap','long-pool','long-origin','io-origin','ram-end'))
def test_word_alias_refuses_unbound_overlapping_or_malformed_intervals(kind):
    module,region,image=inputs()
    row=region.ram_word_literals[0]
    rows=[row]
    changes={'shape':(0x1000,0xffff84ec,0x7f00),
             'bool':(0x1000,0xffff84ec,True,1),'odd':(0x1001,*row[1:]),
             'pool':(0x1008,*row[1:]),'original':(0x1000,0xffff84ed,*row[2:]),
             'positive-original':(0x1000,0x84ec,*row[2:]),
             'negative-alias':(*row[:2],-1,1),'signed-alias':(*row[:2],0x8000,1),
             'extent':(*row[:3],0),'origin-end':(*row[:3],0x10000),
             'alias-end':(*row[:2],0x7fff,2),'code':(*row[:2],0x2000,1),
             'boundary':(*row[:2],0x2010,1),'data':(*row[:2],0x1002,1),
             'ram-end':(*row[:3],0x4000)}
    if kind in changes:rows=[changes[kind]]
    elif kind=='duplicate':rows=[row,row]
    elif kind in ('origin-overlap','alias-overlap','pool-overlap'):
        altered=bytearray(image)
        altered[0x1002:0x1004]=bytes.fromhex('84ed' if kind=='origin-overlap' else '84ee')
        image=bytes(altered)
        rows=[(0x1000,0xffff84ec,0x7f00,2),
              (0x1002,0xffff84ed if kind=='origin-overlap' else 0xffff84ee,
               0x7f02 if kind=='origin-overlap' else 0x7f01,1)]
        if kind=='pool-overlap':rows[1]=row
    elif kind=='long-origin':
        altered=bytearray(image)
        altered[0x1004:0x1008]=bytes.fromhex('ffff84ec')
        image=bytes(altered)
    elif kind=='long-pool':
        altered=bytearray(image)
        altered[0x1004:0x1008]=bytes.fromhex('ffff84ec')
        image=bytes(altered)
        rows=[(0x1006,0xffff84ec,0x7f00,1)]
    elif kind=='io-origin':
        altered=bytearray(image)
        altered[0x1000:0x1002]=bytes.fromhex('c000')
        image=bytes(altered)
        rows=[(0x1000,0xffffc000,0x7f00,1)]
    region=replace(region,ram_word_literals=rows if kind=='list' else tuple(rows))
    with pytest.raises(module.VerificationError):module.build_fixture(region,image)

def test_word_alias_empty_default_keeps_the_exact_bfs_pc_observation_contract():
    import importlib
    module=publication.stock_module()
    pc=importlib.import_module('verify_bfs_pc_observation')
    [region]=[row for row in module.REGIONS if row.key=='jk08a-bfs-rate']
    assert region.ram_word_literals==() and pc.EXPECTED_REGION['ram_word_literals']==[]
    assert pc.registered_region(module.REGIONS) is region

@pytest.mark.parametrize('bindings',(
    ((0x2b75c,0xffff84ec,0x7f00,1),),
    ((0x2b75c,0xffff84ec,0x7f00),),
    ((0x2b75c,0xffff84ec,True,1),),
    ((),),
))
def test_word_alias_bfs_pc_observation_refuses_every_nonempty_binding(bindings):
    import importlib
    module=publication.stock_module()
    pc=importlib.import_module('verify_bfs_pc_observation')
    [region]=[row for row in module.REGIONS if row.key=='jk08a-bfs-rate']
    with pytest.raises(ValueError,match='registered BFS Region contract differs'):
        pc.registered_region((replace(region,ram_word_literals=bindings),))

def test_word_alias_empty_default_preserves_every_original_registered_fixture():
    module=publication.stock_module()
    regions={row.key:row for row in module.REGIONS if row.key not in ('jk08a-injection-prologue','jk08a-channel-pulse')}
    assert len(GOLDEN_FIELDS)==len(GOLDEN_FIXTURES)==48 and set(regions)==set(GOLDEN_FIELDS)
    images={rom:module.stock_image(rom) for rom in {row.rom for row in regions.values()}}
    for key,row in regions.items():
        assert row.ram_word_literals==()
        assert {field:value for field,value in asdict(row).items() if field!='ram_word_literals'}==GOLDEN_FIELDS[key]
        assert hashlib.sha256(module.build_fixture(row,images[row.rom])).hexdigest()==GOLDEN_FIXTURES[key]

